// Agoda — tree diameter, then its endpoints (LeetCode "Find Diameter Endpoints of a Tree" shape).
// Nodes 0..n-1, edges as pairs; the input is a tree (connected, n-1 edges). Iterative BFS: no recursion.
public static class TreeDiameter {
    public static int Diameter(int n, int[][] edges) {
        if (n <= 1) return 0;
        var g = Build(n, edges);
        var d0 = Bfs(g, 0); int a = ArgMax(d0);
        var da = Bfs(g, a);
        return da[ArgMax(da)];
    }

    // s[i] = '1' if node i is an endpoint of SOME longest path, else '0'.
    // A node is such an endpoint exactly when its distance to one of the two BFS-found ends equals the diameter.
    public static string Endpoints(int n, int[][] edges) {
        if (n == 0) return "";
        if (n == 1) return "1";
        var g = Build(n, edges);
        var d0 = Bfs(g, 0); int a = ArgMax(d0);
        var da = Bfs(g, a); int b = ArgMax(da); int D = da[b];
        var db = Bfs(g, b);
        var s = new char[n];
        for (int v = 0; v < n; v++) s[v] = Math.Max(da[v], db[v]) == D ? '1' : '0';
        return new string(s);
    }

    static List<int>[] Build(int n, int[][] edges) {
        if (edges == null || edges.Length != n - 1) throw new ArgumentException("a tree on n nodes has n-1 edges");
        var g = new List<int>[n];
        for (int i = 0; i < n; i++) g[i] = new List<int>();
        foreach (var e in edges) {
            if (e[0] < 0 || e[0] >= n || e[1] < 0 || e[1] >= n) throw new ArgumentOutOfRangeException(nameof(edges));
            g[e[0]].Add(e[1]); g[e[1]].Add(e[0]);
        }
        return g;
    }

    static int[] Bfs(List<int>[] g, int src) {
        var d = new int[g.Length]; Array.Fill(d, -1); d[src] = 0;
        var q = new Queue<int>(); q.Enqueue(src);
        while (q.Count > 0) { int u = q.Dequeue(); foreach (var v in g[u]) if (d[v] < 0) { d[v] = d[u] + 1; q.Enqueue(v); } }
        if (d.Any(x => x < 0)) throw new ArgumentException("the graph is not connected");
        return d;
    }

    static int ArgMax(int[] d) { int m = 0; for (int i = 1; i < d.Length; i++) if (d[i] > d[m]) m = i; return m; }
}
